656	    float rb = uBennyR;
657	    float d = length(vec2(du, dv));
658	    if (d < rb * 8.0) {
659	      float k = uBenny.z;
660	      float rr = max(0.0, d - rb * 0.92);
661	      float rings = smoothstep(0.75, 1.0, 0.5 + 0.5 * sin(d * 5.0 - uTime * 9.0)) * exp(-rr * 0.55) * smoothstep(rb, rb * 1.3, d);
662	      // 05: the magnified near field turned full rings into contour arcs; keep broken ripple fragments
663	      rings *= mix(1.0, 0.45 * smoothstep(0.45, 0.8, vnoise(vec2(atan(du, dv) * 3.0, d * 2.0))), sw);
664	      float back = max(-dv, 0.0);
665	      float wakeV = exp(-abs(abs(du) - back * 0.42 - rb * 0.95) * 6.0) * exp(-back * 0.18) * step(dv, 0.0);
666	      col += uCyanBright * 0.18 * (1.0 - smoothstep(0.0, rb * 0.3, rr)) * k;
667	      col += mix(uCyanBright, vec3(1.3), 0.4) * (rings * 0.22 + wakeV * 0.35) * k * (1.0 - pinkM * 0.5);
668	    }
669	  }
670	
671	  // 04: exactly five glowing chevrons pointing downhill (direction of travel)
672	  if (uChevron.z > 0.5) {
673	    float x = u * vHalfW;
674	    for (int k = 0; k < 5; k++) {
675	      float y = s - (uChevron.x + float(k) * uChevron.y);
676	      if (abs(y) < 2.4 && abs(x) < 1.6) {
677	        // "^" pointing toward +s: tip at y=+1.0, arms sweep back 1.9 units over ±1.15 lateral
678	        float dist = abs(y - (1.0 - abs(x) * 1.65)) * 0.52;
679	        float arm = smoothstep(1.2, 1.1, abs(x));
680	        float core = smoothstep(0.2, 0.11, dist) * arm;
681	        float halo = smoothstep(0.7, 0.0, dist) * smoothstep(1.5, 0.9, abs(x)) * 0.5;
682	        col = mix(col, vec3(1.0), clamp(halo, 0.0, 1.0));
683	        col = mix(col, vec3(2.2, 2.4, 2.5), core);
684	      }
685	    }
686	  }
687	  gl_FragColor = vec4(col, 1.0);
688	  ${FRAG_TAIL}
689	}
690	`;
