692	export interface Ribbon {
693	  mesh: THREE.Mesh;
694	  uniforms: Record<string, THREE.IUniform>;
695	  s0: number;
696	  s1: number;
697	  heightAt(s: number, lateral: number, t: number): number;
698	}
699	
700	export function createRibbon(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): Ribbon {
701	  const { s0, s1, quality } = opts;
702	  const ds = quality === 'high' ? 0.4 : 0.7;
703	  const cols = quality === 'high' ? 18 : 10;
704	  const rows = Math.ceil((s1 - s0) / ds) + 1;
705	  const vertsPerRow = cols + 1 + 2; // + skirt left/right
706	  const n = rows * vertsPerRow;
707	  const pos = new Float32Array(n * 3);
708	  const nor = new Float32Array(n * 3);
709	  const uv = new Float32Array(n * 2);
710	  const halfW = new Float32Array(n);
711	  const speed = new Float32Array(n);
712	  const amp = new Float32Array(n);
713	  const skirt = new Float32Array(n);
714	  const style = new Float32Array(n * 4);
715	  const core = new Float32Array(n);
716	  const tang = new Float32Array(n * 3);
717	  const tmp = new THREE.Vector3();
718	  const nrm = new THREE.Vector3();
719	  let k = 0;
720	  for (let i = 0; i < rows; i++) {
721	    const s = Math.min(s1, s0 + i * ds);
722	    const f = course.sample(s);
723	    const hw = course.widthAt(s) / 2;
724	    const sp = Math.max(3, course.prop(s, 'speed'));
725	    const a = ampAt(course, s);
726	    const bs = bandStyleAt(course, s);
727	    const cl = coreLateral(course, s);
728	    const put = (u: number, lateral: number, h: number, isSkirt: number, nn: THREE.Vector3) => {
729	      tmp.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, h);
730	      tmp.toArray(pos, k * 3);
731	      nn.toArray(nor, k * 3);
732	      f.tan.toArray(tang, k * 3);
733	      uv[k * 2] = u;
734	      uv[k * 2 + 1] = s;
735	      halfW[k] = hw;
736	      speed[k] = sp;
737	      amp[k] = a;
738	      skirt[k] = isSkirt;
739	      for (let q = 0; q < 4; q++) style[k * 4 + q] = bs[q];
740	      core[k] = cl;
741	      k++;
742	    };
743	    // left skirt (below left edge)
744	    put(-1, -hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right).negate());
745	    for (let j = 0; j <= cols; j++) {
746	      const u = -1 + (2 * j) / cols;
747	      const lift = EDGE_LIFT * Math.abs(u) ** 3;
748	      const slope = (EDGE_LIFT * 3 * u * Math.abs(u)) / hw; // d lift / d lateral
749	      nrm.copy(f.up).addScaledVector(f.right, -slope).normalize();
750	      put(u, u * hw, lift, 0, nrm);
751	    }
752	    put(1, hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right));
753	  }
754	  const idx: number[] = [];
755	  for (let i = 0; i < rows - 1; i++) {
756	    for (let j = 0; j < vertsPerRow - 1; j++) {
757	      const a = i * vertsPerRow + j, b = a + 1, c = a + vertsPerRow, d = c + 1;
758	      idx.push(a, c, b, b, c, d);
759	    }
760	  }
761	  const geo = new THREE.BufferGeometry();
762	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
763	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
764	  geo.setAttribute('aUV', new THREE.BufferAttribute(uv, 2));
765	  geo.setAttribute('aHalfW', new THREE.BufferAttribute(halfW, 1));
766	  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
767	  geo.setAttribute('aAmp', new THREE.BufferAttribute(amp, 1));
768	  geo.setAttribute('aSkirt', new THREE.BufferAttribute(skirt, 1));
769	  geo.setAttribute('aStyle', new THREE.BufferAttribute(style, 4));
770	  geo.setAttribute('aCore', new THREE.BufferAttribute(core, 1));
771	  geo.setAttribute('aTan', new THREE.BufferAttribute(tang, 3));
772	  geo.setIndex(idx);
773	  geo.computeBoundingSphere();
774	
775	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08');
776	  const uniforms = withFog({
777	    uTime: { value: 0 },
778	    uCyanDeep: { value: RIBBON_PAL.cyanDeep.clone() },
779	    uCyan: { value: RIBBON_PAL.cyan.clone() },
780	    uCyanBright: { value: RIBBON_PAL.cyanBright.clone() },
781	    uPinkDeep: { value: RIBBON_PAL.pinkDeep.clone() },
782	    uPink: { value: RIBBON_PAL.pink.clone() },
783	    uPinkLight: { value: RIBBON_PAL.pinkLight.clone() },
784	    uFoam: { value: PALETTE.foam.clone() },
785	    uFoamLav: { value: PALETTE.foamLav.clone() },
786	    uHaze: { value: PALETTE.haze.clone() },
787	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
788	    uBenny: { value: new THREE.Vector3(0, 0, 0) },
789	    uBennyR: { value: 0.7 },
790	    uChevron: { value: new THREE.Vector3(st04.s0 + 8.5, 3.6, 1) },
791	    uOutro: { value: new THREE.Vector2(0, st08.s0) },
792	    uHide: { value: new THREE.Vector4(st03.s0, st04.s0, 0, 0) },
793	    uC5Deep: { value: RIVER05_PAL.cyanDeep.clone() },
794	    uC5: { value: RIVER05_PAL.cyan.clone() },
795	    uC5Bright: { value: RIVER05_PAL.cyanBright.clone() },
796	    uC5Streak: { value: RIVER05_PAL.cyanStreak.clone() },
797	    uP5Deep: { value: RIVER05_PAL.pinkDeep.clone() },
798	    uP5: { value: RIVER05_PAL.pink.clone() },
799	    uP5Light: { value: RIVER05_PAL.pinkLight.clone() },
800	    uP5Streak: { value: RIVER05_PAL.pinkStreak.clone() },
801	    uFlow05: { value: course.stage('05').speed * FLOW05 },
802	  });
803	  const mat = new THREE.ShaderMaterial({
804	    uniforms,
805	    vertexShader: VERT,
806	    fragmentShader: FRAG,
807	    fog: true,
808	    side: THREE.DoubleSide,
809	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
810	  });
811	  const mesh = new THREE.Mesh(geo, mat);
812	  mesh.name = 'water_ribbon';
813	  mesh.frustumCulled = false; // one long mesh spanning the whole course
814	  return {
815	    mesh,
816	    uniforms,
817	    s0,
818	    s1,
819	    heightAt(s, lateral, t) {
820	      const hw = course.widthAt(s) / 2;
821	      return ribbonWave(lateral / hw, s, t, ampAt(course, s));
822	    },
823	  };
824	}
