108	/**
109	 * Rainbow water palette (sRGB hex → linear THREE.Color, ready for uniforms).
110	 * Base hues are scaled below the NeutralToneMapping knee (~0.76 linear) so the renderer does not
111	 * desaturate them toward pastel; only highlights/sparkles/foam exceed 1.0 (and feed bloom).
112	 */
113	const knee = (hex: string, k = 0.74) => new THREE.Color(hex).multiplyScalar(k);
114	export const PALETTE = {
115	  cyanDeep: knee('#0a62f0', 0.72),
116	  cyan: knee('#08c0ff'),
117	  cyanBright: knee('#56f0ff', 0.8),
118	  pink: knee('#ff149f'),
119	  pinkLight: knee('#ff4cc0', 0.78),
120	  magenta: new THREE.Color('#e01ea0'),
121	  foam: new THREE.Color('#ffffff'),
122	  foamLav: new THREE.Color('#efe2ff'),
123	  haze: new THREE.Color('#ffd6f4'),
124	};
