131	/** standard tail: tonemapping + colour space + fog (call with gl_FragColor already set) */
132	export const FRAG_TAIL = /* glsl */ `
133	  #include <tonemapping_fragment>
134	  #include <colorspace_fragment>
135	  #include <fog_fragment>
136	`;
